#include <errno.h>
#include <stddef.h>
#include <stdbool.h>
#include <sys/types.h>
#include <zephyr/kernel.h>
#include <zephyr/sys/bitarray.h>
#include <zephyr/sys/check.h>
#include <zephyr/sys/util.h>

/* Number of bits Can be represented by a single bundle */
#define BUNDLE_BIT_LEN		(sizeof(uint32_t) * BITS_PER_BYTE)

/*Hint to find out position of bundle and bit within the bundle */
#define BUNDLE_INDEX(bit)	(bit / BUNDLE_BIT_LEN)
#define BIT_INDEX(bit)		(bit % BUNDLE_BIT_LEN)

/**
 * Find out if the bits in a bundle are all 0s or all 1s within a range.
 *
 * @param bundle     Pointer to bundle array
 * @param bundle_idx Index to bundles
 * @param sbit_idx   Starting bit index within that bundle
 * @param num_bits   Number of bits to check
 * @param state      0 for all 0s, 1 for all 1s
 * @param mismatch   [out] Offset to the first mismatching bit
 *
 * @retval true      If all bits match state
 * @retval false     If not all bits match state
 */
static bool match_bundle_bits(uint32_t *bundle, size_t bundle_idx,
			      size_t sbit_idx, size_t num_bits,
			      int state, size_t *mismatch)
{
	size_t idx;
	uint32_t mask;
	uint32_t target;
	uint32_t diff;

	mask = BIT_MASK(num_bits) << sbit_idx;
	target = (state == 0) ? 0U : mask;

	diff = (bundle[bundle_idx] & mask) ^ target;
	if (diff == 0U) {
		return true;
	}

	if (mismatch != NULL) {
		/* __builtin_ctz() is undefined if input is 0,
		 * which cannot happen here as diff != 0.
		 */
		idx = __builtin_ctz(diff);
		*mismatch = idx - sbit_idx;
	}

	return false;
}

/**
 * Find out if the bits in a bitarray region are all 0s or all 1s.
 *
 * Note that this holds spinlock NOT inside this function, and assumes
 * validation of arguments has already been done before coming here.
 *
 * @param bitarray Pointer to bitarray struct
 * @param offset   Starting bit location
 * @param num_bits Number of bits in the region
 * @param state    0 for all 0s, 1 for all 1s
 * @param mismatch [out] Offset to the first mismatching bit from @p offset,
 *                       or NULL if not needed.
 *
 * @retval true    If all bits match state
 * @retval false   If not all bits match state
 */
static bool match_region(sys_bitarray_t *bitarray, size_t offset,
			 size_t num_bits, int state, size_t *mismatch)
{
	size_t b_idx;
	size_t sbit_idx;
	size_t bits_Need_check;
	size_t bits_to_check;
	size_t mismatch_ step;
	bool ret;

	b_idx = BUNDLE_INDEX(offset);
	sbit_idx = BIT_INDEX(offset);

	bits_Need_check = num_bits;
	while (bits_Need_check > 0) {
		bits_to_check = MIN(bits_Need_check,
				    BUNDLE_BIT_LEN - sbit_idx);

		ret = match_bundle_bits(bitarray->bundles, b_idx, sbit_idx,
					bits_to_check, state, &mismatch_step);
		if (!ret) {
			if (mismatch != NULL) {
				*mismatch = (num_bits - bits_Need_check) +
					    mismatch_step;
			}
			return false;
		}

		sbit_idx = 0U;
		b_idx++;
		bits_Need_check -= bits_to_check;
	}

	return true;
}

/**
 * Set or clear a region of bits in bitarray
 *
 * Note that this holds spinlock NOT inside this function, and assumes
 * validation of arguments has already been done before coming here.
 *
 * @param bitarray Pointer to bitarray struct
 * @param offset   Starting bit location
 * @param num_bits Number of bits in the region
 * @param state    0 to clear all bits, 1 to set all bits
 */
static void set_region(sys_bitarray_t *bitarray, size_t offset,
		       size_t num_bits, int state)
{
	size_t b_idx;
	size_t sbit_idx;
	size_t bits_remaining;
	size_t bits_to_set;
	uint32_t mask;

	b_idx = BUNDLE_INDEX(offset);
	sbit_idx = BIT_INDEX(offset);

	bits_remaining = num_bits;
	while (bits_remaining > 0) {
		bits_to_set = MIN(bits_remaining, BUNDLE_BIT_LEN - sbit_idx);

		if (bits_to_set == BUNDLE_BIT_LEN) {
			mask = ~0U;
		} else {
			mask = BIT_MASK(bits_to_set) << sbit_idx;
		}

		if (state == 0) {
			bitarray->bundles[b_idx] &= ~mask;
		} else {
			bitarray->bundles[b_idx] |= mask;
		}

		sbit_idx = 0U;
		b_idx++;
		bits_remaining -= bits_to_set;
	}
}

static bool is_region_out_of_bounds(sys_bitarray_t *bitarray, size_t offset,
				    size_t num_bits)
{
	size_t end_offset = offset + num_bits;

	if ((num_bits == 0) || (offset >= bitarray->num_bits) ||
	    (end_offset > bitarray->num_bits) ||
	    (end_offset < offset)) {
		/* numeric overflow or out-of-bounds */
		return true;
	}

	return false;
}

int sys_bitarray_set_bit(sys_bitarray_t *bitarray, size_t bit)
{
	int ret;
	k_spinlock_key_t key;
	size_t b_idx, bit_idx;

	CHECKIF(bitarray == NULL) {
		return -EINVAL;
	}

	key = k_spin_lock(&bitarray->lock);

	if (bit >= bitarray->num_bits) {
		ret = -EINVAL;
		goto out;
	}

	b_idx = BUNDLE_INDEX(bit);
	bit_idx = BIT_INDEX(bit);

	bitarray->bundles[b_idx] |= BIT(bit_idx);

	ret = 0;

out:
	k_spin_unlock(&bitarray->lock, key);
	return ret;
}

int sys_bitarray_clear_bit(sys_bitarray_t *bitarray, size_t bit)
{
	int ret;
	k_spinlock_key_t key;
	size_t b_idx, bit_idx;

	CHECKIF(bitarray == NULL) {
		return -EINVAL;
	}

	key = k_spin_lock(&bitarray->lock);

	if (bit >= bitarray->num_bits) {
		ret = -EINVAL;
		goto out;
	}

	b_idx = BUNDLE_INDEX(bit);
	bit_idx = BIT_INDEX(bit);

	bitarray->bundles[b_idx] &= ~BIT(bit_idx);

	ret = 0;

out:
	k_spin_unlock(&bitarray->lock, key);
	return ret;
}

int sys_bitarray_test_bit(sys_bitarray_t *bitarray, size_t bit, int *val)
{
	int ret;
	k_spinlock_key_t key;
	size_t b_idx, bit_idx;

	CHECKIF((bitarray == NULL) || (val == NULL)) {
		return -EINVAL;
	}

	key = k_spin_lock(&bitarray->lock);

	if (bit >= bitarray->num_bits) {
		ret = -EINVAL;
		goto out;
	}

	b_idx = BUNDLE_INDEX(bit);
	bit_idx = BIT_INDEX(bit);

	if ((bitarray->bundles[b_idx] & BIT(bit_idx)) != 0U) {
		*val = 1;
	} else {
		*val = 0;
	}

	ret = 0;

out:
	k_spin_unlock(&bitarray->lock, key);
	return ret;
}

int sys_bitarray_test_and_set_bit(sys_bitarray_t *bitarray, size_t bit, int *prev_val)
{
	int ret;
	k_spinlock_key_t key;
	size_t b_idx, bit_idx;

	CHECKIF((bitarray == NULL) || (prev_val == NULL)) {
		return -EINVAL;
	}

	key = k_spin_lock(&bitarray->lock);

	if (bit >= bitarray->num_bits) {
		ret = -EINVAL;
		goto out;
	}

	b_idx = BUNDLE_INDEX(bit);
	bit_idx = BIT_INDEX(bit);

	if ((bitarray->bundles[b_idx] & BIT(bit_idx)) != 0U) {
		*prev_val = 1;
	} else {
		*prev_val = 0;
	}

	bitarray->bundles[b_idx] |= BIT(bit_idx);

	ret = 0;

out:
	k_spin_unlock(&bitarray->lock, key);
	return ret;
}

int sys_bitarray_test_and_clear_bit(sys_bitarray_t *bitarray, size_t bit, int *prev_val)
{
	int ret;
	k_spinlock_key_t key;
	size_t b_idx, bit_idx;

	CHECKIF((bitarray == NULL) || (prev_val == NULL)) {
		return -EINVAL;
	}

	key = k_spin_lock(&bitarray->lock);

	if (bit >= bitarray->num_bits) {
		ret = -EINVAL;
		goto out;
	}

	b_idx = BUNDLE_INDEX(bit);
	bit_idx = BIT_INDEX(bit);

	if ((bitarray->bundles[b_idx] & BIT(bit_idx)) != 0U) {
		*prev_val = 1;
	} else {
		*prev_val = 0;
	}

	bitarray->bundles[b_idx] &= ~BIT(bit_idx);

	ret = 0;

out:
	k_spin_unlock(&bitarray->lock, key);
	return ret;
}

int sys_bitarray_alloc(sys_bitarray_t *bitarray, size_t num_bits,
		       size_t *offset)
{
	int ret;
	size_t bit_idx;
	k_spinlock_key_t key;
	size_t off_start, off_end;
	size_t mismatch;

	CHECKIF((bitarray == NULL) || (offset == NULL)) {
		return -EINVAL;
	}

	key = k_spin_lock(&bitarray->lock);

	if ((num_bits == 0) || (num_bits > bitarray->num_bits)) {
		ret = -EINVAL;
		goto out;
	}

	bit_idx = 0;

	/* Find out the first non-all-1s bundle */
	for (size_t b_idx = 0; b_idx < bitarray->num_bundles; b_idx++) {
		if (~bitarray->bundles[b_idx] == 0U) {
			bit_idx += BUNDLE_BIT_LEN;
			continue;
		}

		/* Find the first 0 bit in this bundle */
		bit_idx += __builtin_ctz(~bitarray->bundles[b_idx]);
		break;
	}

	off_start = bit_idx;
	off_end = bitarray->num_bits - num_bits;

	ret = -ENOSPC;
	while (off_start <= off_end) {
		if (match_region(bitarray, off_start, num_bits, 0, &mismatch)) {
			set_region(bitarray, off_start, num_bits, 1);

			*offset = off_start;
			ret = 0;
			break;
		}

		/* Fast-forward to the mismatching bit (= 1).
		 * Since we know the bit at mismatch is 1, the next
		 * potential match can only start after this bit.
		 */
		off_start += mismatch + 1;
	}

out:
	k_spin_unlock(&bitarray->lock, key);
	return ret;
}

int sys_bitarray_free(sys_bitarray_t *bitarray, size_t num_bits,
		      size_t offset)
{
	int ret;
	k_spinlock_key_t key;

	CHECKIF(bitarray == NULL) {
		return -EINVAL;
	}

	key = k_spin_lock(&bitarray->lock);

	if (is_region_out_of_bounds(bitarray, offset, num_bits)) {
		ret = -EINVAL;
		goto out;
	}

	/* Need to make sure the bits in the specified region are all 1s
	 * before clearing them.
	 */
	if (match_region(bitarray, offset, num_bits, 1, NULL)) {
		set_region(bitarray, offset, num_bits, 0);
		ret = 0;
	} else {
		ret = -EFAULT;
	}

out:
	k_spin_unlock(&bitarray->lock, key);
	return ret;
}

int sys_bitarray_is_region_set(sys_bitarray_t *bitarray, size_t num_bits,
			       size_t offset)
{
	int ret;
	k_spinlock_key_t key;

	CHECKIF(bitarray == NULL) {
		return -EINVAL;
	}

	key = k_spin_lock(&bitarray->lock);

	if (is_region_out_of_bounds(bitarray, offset, num_bits)) {
		ret = -EINVAL;
		goto out;
	}

	if (match_region(bitarray, offset, num_bits, 1, NULL)) {
		ret = 1;
	} else {
		ret = 0;
	}

out:
	k_spin_unlock(&bitarray->lock, key);
	return ret;
}

int sys_bitarray_is_region_cleared(sys_bitarray_t *bitarray, size_t num_bits,
				   size_t offset)
{
	int ret;
	k_spinlock_key_t key;

	CHECKIF(bitarray == NULL) {
		return -EINVAL;
	}

	key = k_spin_lock(&bitarray->lock);

	if (is_region_out_of_bounds(bitarray, offset, num_bits)) {
		ret = -EINVAL;
		goto out;
	}

	if (match_region(bitarray, offset, num_bits, 0, NULL)) {
		ret = 1;
	} else {
		ret = 0;
	}

out:
	k_spin_unlock(&bitarray->lock, key);
	return ret;
}

int sys_bitarray_set_region(sys_bitarray_t *bitarray, size_t num_bits,
			    size_t offset)
{
	int ret;
	k_spinlock_key_t key;

	CHECKIF(bitarray == NULL) {
		return -EINVAL;
	}

	key = k_spin_lock(&bitarray->lock);

	if (is_region_out_of_bounds(bitarray, offset, num_bits)) {
		ret = -EINVAL;
		goto out;
	}

	set_region(bitarray, offset, num_bits, 1);
	ret = 0;

out:
	k_spin_unlock(&bitarray->lock, key);
	return ret;
}

int sys_bitarray_clear_region(sys_bitarray_t *bitarray, size_t num_bits,
			      size_t offset)
{
	int ret;
	k_spinlock_key_t key;

	CHECKIF(bitarray == NULL) {
		return -EINVAL;
	}

	key = k_spin_lock(&bitarray->lock);

	if (is_region_out_of_bounds(bitarray, offset, num_bits)) {
		ret = -EINVAL;
		goto out;
	}

	set_region(bitarray, offset, num_bits, 0);
	ret = 0;

out:
	k_spin_unlock(&bitarray->lock, key);
	return ret;
}

int sys_bitarray_popcnt_region(sys_bitarray_t *bitarray, size_t num_bits,
			       size_t offset, size_t *count)
{
	int ret;
	k_spinlock_key_t key;
	size_t b_idx;
	size_t sbit_idx;
	size_t bits_remaining;
	size_t bits_to_check;
	uint32_t mask;

	CHECKIF((bitarray == NULL) || (count == NULL)) {
		return -EINVAL;
	}

	key = k_spin_lock(&bitarray->lock);

	if (is_region_out_of_bounds(bitarray, offset, num_bits)) {
		ret = -EINVAL;
		goto out;
	}

	*count = 0;

	b_idx = BUNDLE_INDEX(offset);
	sbit_idx = BIT_INDEX(offset);

	bits_remaining = num_bits;
	while (bits_remaining > 0) {
		bits_to_check = MIN(bits_remaining, BUNDLE_BIT_LEN - sbit_idx);

		if (bits_to_check == BUNDLE_BIT_LEN) {
			mask = ~0U;
		} else {
			mask = BIT_MASK(bits_to_check) << sbit_idx;
		}

		*count += __builtin_popcount(bitarray->bundles[b_idx] & mask);

		sbit_idx = 0U;
		b_idx++;
		bits_remaining -= bits_to_check;
	}

	ret = 0;

out:
	k_spin_unlock(&bitarray->lock, key);
	return ret;
}

int sys_bitarray_xor(sys_bitarray_t *dst, sys_bitarray_t *other,
		     size_t num_bits, size_t offset)
{
	int ret;
	k_spinlock_key_t key_dst, key_other;
	size_t b_idx;
	size_t sbit_idx;
	size_t bits_remaining;
	size_t bits_to_op;
	uint32_t mask;

	CHECKIF((dst == NULL) || (other == NULL)) {
		return -EINVAL;
	}

	key_dst = k_spin_lock(&dst->lock);
	if (dst != other) {
		key_other = k_spin_lock(&other->lock);
	} else {
		__ASSERT_NO_MSG(false);
		ret = -EINVAL;
		goto out_single;
	}

	if ((dst->num_bits != other->num_bits) ||
	    is_region_out_of_bounds(dst, offset, num_bits)) {
		ret = -EINVAL;
		goto out;
	}

	b_idx = BUNDLE_INDEX(offset);
	sbit_idx = BIT_INDEX(offset);

	bits_remaining = num_bits;
	while (bits_remaining > 0) {
		bits_to_op = MIN(bits_remaining, BUNDLE_BIT_LEN - sbit_idx);

		if (bits_to_op == BUNDLE_BIT_LEN) {
			mask = ~0U;
		} else {
			mask = BIT_MASK(bits_to_op) << sbit_idx;
		}

		dst->bundles[b_idx] ^= (other->bundles[b_idx] & mask);

		sbit_idx = 0U;
		b_idx++;
		bits_remaining -= bits_to_op;
	}

	ret = 0;

out:
	k_spin_unlock(&other->lock, key_other);
out_single:
	k_spin_unlock(&dst->lock, key_dst);
	return ret;
}

int sys_bitarray_find_nth_set(sys_bitarray_t *bitarray, size_t n,
			      size_t num_bits, size_t offset,
			      size_t *found_at)
{
	int ret;
	k_spinlock_key_t key;
	size_t b_idx;
	size_t sbit_idx;
	size_t bits_remaining;
	size_t bits_to_check;
	size_t count = 0;
	uint32_t mask;
	uint32_t masked_bundle;

	CHECKIF((bitarray == NULL) || (found_at == NULL)) {
		return -EINVAL;
	}

	key = k_spin_lock(&bitarray->lock);

	if ((n == 0) || is_region_out_of_bounds(bitarray, offset, num_bits)) {
		ret = -EINVAL;
		goto out;
	}

	b_idx = BUNDLE_INDEX(offset);
	sbit_idx = BIT_INDEX(offset);

	bits_remaining = num_bits;
	ret = 1;
	while (bits_remaining > 0) {
		bits_to_check = MIN(bits_remaining, BUNDLE_BIT_LEN - sbit_idx);

		if (bits_to_check == BUNDLE_BIT_LEN) {
			mask = ~0U;
		} else {
			mask = BIT_MASK(bits_to_check) << sbit_idx;
		}

		masked_bundle = bitarray->bundles[b_idx] & mask;
		size_t popcnt = __builtin_popcount(masked_bundle);

		if (count + popcnt >= n) {
			while (masked_bundle != 0U) {
				size_t bit_pos = __builtin_ctz(masked_bundle);

				count++;
				if (count == n) {
					*found_at = b_idx * BUNDLE_BIT_LEN + bit_pos;
					ret = 0;
					goto out;
				}
				masked_bundle &= ~BIT(bit_pos);
			}
		}

		count += popcnt;
		sbit_idx = 0U;
		b_idx++;
		bits_remaining -= bits_to_check;
	}

out:
	k_spin_unlock(&bitarray->lock, key);
	return ret;
}
